      galleryImages: "[\"https://barryferrier.com/media/k2/galleries/38/1998%20Kukanarri%20Show0.jpg\", \"https://barryferrier.com/media/k2/galleries/38/1998%20Kukanarri%20Show3.jpg\"]",
